window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8de2b056c47f2c91"]={"versions": [{"id": "FIG-8de2b056c47f2c91", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm der AUTOSAR Classic Platform zur Veranschaulichung der Signalabstraktionsstufen von physischer Hardware bis zur Anwendungsebene. Das Diagramm ordnet die AUTOSAR-Ebenen vertikal an und stellt ihnen rechts Signalbegriffe sowie Abstraktionsebenen entlang eines aufsteigenden Signalfluss- und Abstraktionspfeils gegenüber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in folgende Komponenten und Schichten:</p>\n<ul class=\"fig-list\"><li>Oberste Ebene: Software Components bestehend aus Application Software Component, Actuator Software Component und Sensor Software Component, jeweils mit AUTOSAR Interface.\n</li><li>Laufzeitumgebung: AUTOSAR Runtime Environment (RTE).\n</li><li>ECU-Abstraktionsschicht: I/O HW Abstraction mit aufgesetztem AUTOSAR Interface.\n</li><li>Mikrocontroller-Abstraktionsschicht: MCAL drivers.\n</li><li>Hardware-Ebene: Microcontroller sowie darunterliegende ECU Hardware.\n</li></ul>\n<p class=\"fig-p\">Rechts zugeordnete Signal- und Abstraktionsebenen:</p>\n<ul class=\"fig-list\"><li>Signalbegriffe: Electrical Signal (auf Ebene von ECU Hardware und Microcontroller), ECU Signal (an der Schnittstelle oberhalb der I/O HW Abstraction), AUTOSAR Signal (auf Ebene der Software Components).\n</li><li>Abstraktionsschritte entlang des vertikalen Pfeils: Microcontroller Abstraction, ECU Abstraction, VFB (Virtual Functional Bus).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt die Transformation und Abstraktion eines Signals von der physischen zur logischen Ebene dar:</p>\n<ul class=\"fig-list\"><li>Auf Hardware- und Mikrocontroller-Ebene liegt das Signal als physisches/elektrisches Signal (Electrical Signal) vor.\n</li><li>Die MCAL-Treiber bieten die Mikrocontroller-Abstraktion (Microcontroller Abstraction).\n</li><li>Die I/O Hardware Abstraction kapselt ECU-spezifische Hardwareanbindungen (ECU Abstraction) und stellt das Signal über ein AUTOSAR Interface als ECU Signal bereit.\n</li><li>Über die RTE wird das ECU Signal auf VFB-Ebene in ein AUTOSAR Signal überführt und den Software-Komponenten (Sensor-, Actuator-, Application-SWC) bereitgestellt bzw. von diesen empfangen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als architektonische Leitlinie für die Implementierung der I/O-Hardware-Abstraktion (IO HW Abstraction) und der zugehörigen Signalpfade in AUTOSAR Classic. Entwickler müssen sicherstellen, dass anwendungsspezifische SWCs (Sensoren/Aktoren/Applikation) nicht direkt auf MCAL-Treiber oder Hardware zugreifen, sondern die Abstraktion über AUTOSAR Interfaces und RTE nutzen, wobei das ECU Signal als hardwareunabhängiges Zwischenstadium zwischen MCAL/Hardware und der VFB-Signalebene (AUTOSAR Signal) fungiert.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-303b956341b2e418", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm der AUTOSAR Classic Platform zur Veranschaulichung der Signalabstraktionsstufen von physischer Hardware bis zur Anwendungsebene. Das Diagramm ordnet die AUTOSAR-Ebenen vertikal an und stellt ihnen rechts Signalbegriffe sowie Abstraktionsebenen entlang eines aufsteigenden Signalfluss- und Abstraktionspfeils gegenüber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in folgende Komponenten und Schichten:</p>\n<ul class=\"fig-list\"><li>Oberste Ebene: Software Components bestehend aus Application Software Component, Actuator Software Component und Sensor Software Component, jeweils mit AUTOSAR Interface.\n</li><li>Laufzeitumgebung: AUTOSAR Runtime Environment (RTE).\n</li><li>ECU-Abstraktionsschicht: I/O HW Abstraction mit aufgesetztem AUTOSAR Interface.\n</li><li>Mikrocontroller-Abstraktionsschicht: MCAL drivers.\n</li><li>Hardware-Ebene: Microcontroller sowie darunterliegende ECU Hardware.\n</li></ul>\n<p class=\"fig-p\">Rechts zugeordnete Signal- und Abstraktionsebenen:</p>\n<ul class=\"fig-list\"><li>Signalbegriffe: Electrical Signal (auf Ebene von ECU Hardware und Microcontroller), ECU Signal (an der Schnittstelle oberhalb der I/O HW Abstraction), AUTOSAR Signal (auf Ebene der Software Components).\n</li><li>Abstraktionsschritte entlang des vertikalen Pfeils: Microcontroller Abstraction, ECU Abstraction, VFB (Virtual Functional Bus).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt die Transformation und Abstraktion eines Signals von der physischen zur logischen Ebene dar:</p>\n<ul class=\"fig-list\"><li>Auf Hardware- und Mikrocontroller-Ebene liegt das Signal als physisches/elektrisches Signal (Electrical Signal) vor.\n</li><li>Die MCAL-Treiber bieten die Mikrocontroller-Abstraktion (Microcontroller Abstraction).\n</li><li>Die I/O Hardware Abstraction kapselt ECU-spezifische Hardwareanbindungen (ECU Abstraction) und stellt das Signal über ein AUTOSAR Interface als ECU Signal bereit.\n</li><li>Über die RTE wird das ECU Signal auf VFB-Ebene in ein AUTOSAR Signal überführt und den Software-Komponenten (Sensor-, Actuator-, Application-SWC) bereitgestellt bzw. von diesen empfangen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als architektonische Leitlinie für die Implementierung der I/O-Hardware-Abstraktion (IO HW Abstraction) und der zugehörigen Signalpfade in AUTOSAR Classic. Entwickler müssen sicherstellen, dass anwendungsspezifische SWCs (Sensoren/Aktoren/Applikation) nicht direkt auf MCAL-Treiber oder Hardware zugreifen, sondern die Abstraktion über AUTOSAR Interfaces und RTE nutzen, wobei das ECU Signal als hardwareunabhängiges Zwischenstadium zwischen MCAL/Hardware und der VFB-Signalebene (AUTOSAR Signal) fungiert.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8de2b056c47f2c91", "to": "FIG-303b956341b2e418", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
